INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002db',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss business ethics at B2","Use Wirtschaftsethik vocabulary","Talk about corporate ethics, stakeholder theory, and Germany''s social market economy ethics"],"explanation":{"intro":"Business ethics vocabulary covers corporate ethics, stakeholder theory, and the moral foundations of market economies at B2.","culturalNote":"Wirtschaftsethik: Germany: Soziale Marktwirtschaft (social market economy — Ludwig Erhard — ''Wohlstand für alle'' — 1957) — built-in ethical commitment to social balance. Key: Unternehmensverantwortung (corporate responsibility — CSR). Stakeholder theory (Freeman 1984) vs. shareholder primacy (Friedman — profit maximisation). Sozialpartnerschaft (social partnership — co-determination — Mitbestimmungsgesetz 1976 — workers on supervisory boards). Ethics in banking: Raiffeisen/cooperative banks vs. investment banks. Key debate: Greenwashing. Lieferkettensorgfaltspflichtengesetz (Supply Chain Due Diligence Act — 2023 — German companies must check human rights in supply chains). Whistleblowing. Korruption (corruption — Transparency International CPI — Germany ~rank 9/180). Gewinnmaximierung (profit maximisation) vs. Gemeinwohlorientierung (common good orientation)."},"examples":[{"german":"Wirtschaftsethik stellt grundlegende Fragen, die über betriebliche Compliance hinausgehen: Welche Ziele verfolgt ein Unternehmen legitimerweise? Gegenüber wem trägt es Verantwortung? Wie lassen sich wirtschaftliche Rationalität und moralische Rücksichtnahme vereinbaren? In der sozialen Marktwirtschaft ist die Antwort institutionell verankert: Mitbestimmung, Tarifverhandlungen und Sozialsicherung sind strukturelle Antworten auf ethische Fragen.","english":"Business ethics raises fundamental questions that go beyond operational compliance: which goals may a company legitimately pursue? To whom does it bear responsibility? How can economic rationality and moral consideration be reconciled? In the social market economy, the answer is institutionally anchored: co-determination, collective bargaining, and social security are structural answers to ethical questions."},{"german":"Das Lieferkettensorgfaltspflichtengesetz markiert einen Paradigmenwechsel in der deutschen Wirtschaftsethik: Es überträgt Unternehmen Verantwortung für Menschenrechtsverletzungen in ihren globalen Lieferketten — auch wenn diese von rechtlich selbstständigen Vorlieferanten begangen werden. Das Prinzip: Wer von globalen Wertschöpfungsketten profitiert, muss für die Bedingungen einstehen, unter denen dieser Mehrwert entsteht.","english":"The Supply Chain Due Diligence Act marks a paradigm shift in German business ethics: it transfers to companies responsibility for human rights violations in their global supply chains — even if these are committed by legally independent upstream suppliers. The principle: those who profit from global value chains must stand for the conditions under which this added value arises."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss corporate responsibility, Germany''s supply chain law, and social market economy ethics at B2."}}',
'{"items":[{"word":"die Compliance","translation":"compliance","pronunciation":"dee kom-PLY-ents","example":"Betriebliche Compliance."},{"word":"die Rücksichtnahme","translation":"consideration","pronunciation":"dee RÜK-zikht-nah-meh","example":"Moralische Rücksichtnahme."},{"word":"verankern","translation":"to anchor","pronunciation":"fer-ANK-ern","example":"Institutionell verankert."},{"word":"der Vorlieferant","translation":"upstream supplier","pronunciation":"dayr FOR-lee-feh-rant","example":"Rechtlich selbstständiger Vorlieferant."},{"word":"einstehen für","translation":"to stand for/answer for","pronunciation":"YN-shtay-en für","example":"Für Bedingungen einstehen."},{"word":"der Mehrwert","translation":"added value/surplus value","pronunciation":"dayr MAYR-vert","example":"Mehrwert entsteht."}]}',
'{"title":"Wer von X profitiert, muss für Y einstehen — those who profit from X must answer for Y","pattern":"wer von X profitiert, muss für Y einstehen = those who profit from X must stand for/answer for Y (wer = whoever/those who; von X profitieren = to profit from X; für Y einstehen = to stand for/answer for Y — moral accountability)","explanation":"Wer von X profitiert = those who profit from X (wer as relative pronoun — ''whoever''). Für Y einstehen = to stand for Y, to answer for Y (einstehen für = separable — stands up for, is accountable for). The pattern creates a moral link between benefit and accountability: those who benefit from something must also bear responsibility for its conditions. Often used to argue for extended moral/legal responsibility (supply chains, investment, colonialism). Compare: wer X genießt, muss Y tragen (those who enjoy X must bear Y), Haftung (liability — legal), Mitverantwortung (shared responsibility), Verantwortungsübernahme (taking responsibility).","examples":[{"sentence":"Wer von billigen Produkten profitiert, muss für die Arbeitsbedingungen einstehen.","translation":"Those who profit from cheap products must answer for the working conditions."},{"sentence":"Wer von dieser Entscheidung profitiert, muss für deren Konsequenzen einstehen.","translation":"Those who profit from this decision must answer for its consequences."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Einstehen für'' means?","options":["to stand for/answer for","to be responsible for","to vouch for","to account for"],"correctAnswer":"to stand for/answer for"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Supply Chain Due Diligence Act marks a paradigm shift in German business ethics: it transfers to companies responsibility for human rights violations in their global supply chains — even if these are committed by legally independent upstream suppliers. The principle: those who profit from global value chains must stand for the conditions under which this added value arises.","options":["Das Lieferkettensorgfaltspflichtengesetz markiert einen Paradigmenwechsel in der deutschen Wirtschaftsethik: Es überträgt Unternehmen Verantwortung für Menschenrechtsverletzungen in ihren globalen Lieferketten — auch wenn diese von rechtlich selbstständigen Vorlieferanten begangen werden. Das Prinzip: Wer von globalen Wertschöpfungsketten profitiert, muss für die Bedingungen einstehen, unter denen dieser Mehrwert entsteht.","Deutsche Unternehmen haften jetzt für Menschenrechtsverletzungen ihrer Zulieferer.","Wer von globalen Lieferketten profitiert, trägt Mitverantwortung für deren Bedingungen.","Das Lieferkettengesetz macht Unternehmen für Missstände in ihrer Lieferkette verantwortlich."],"correctAnswer":"Das Lieferkettensorgfaltspflichtengesetz markiert einen Paradigmenwechsel in der deutschen Wirtschaftsethik: Es überträgt Unternehmen Verantwortung für Menschenrechtsverletzungen in ihren globalen Lieferketten — auch wenn diese von rechtlich selbstständigen Vorlieferanten begangen werden. Das Prinzip: Wer von globalen Wertschöpfungsketten profitiert, muss für die Bedingungen einstehen, unter denen dieser Mehrwert entsteht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wer von billigen Produkten profitiert, muss für die Arbeitsbedingungen ___.","options":["einstehen","haften","antworten","verantworten"],"correctAnswer":"einstehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Those who profit from this decision must answer for its consequences","wordBankItems":["Wer","von","dieser","Entscheidung","profitiert",",","muss","für","deren","Konsequenzen","einstehen","."],"correctAnswer":"Wer von dieser Entscheidung profitiert , muss für deren Konsequenzen einstehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Mehrwert'' means?","options":["added value/surplus value","profit","gain","benefit"],"correctAnswer":"added value/surplus value"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002dc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss corporate responsibility at B2","Use Unternehmensverantwortung vocabulary","Talk about CSR, ESG, and corporate governance in Germany"],"explanation":{"intro":"Corporate responsibility vocabulary covers CSR, ESG frameworks, and Germany''s approach to corporate governance at B2.","culturalNote":"Unternehmensverantwortung: Key: CSR (Corporate Social Responsibility) — voluntary → mandatory (EU CSRD — Corporate Sustainability Reporting Directive 2023). ESG (Environmental, Social, Governance) — investor framework. Germany: Mitbestimmung (co-determination) as structural CSR. Gemeinwohlökonomie (Economy for the Common Good — Christian Felber — alternative accounting). Nachhaltigkeitsbericht (sustainability report). Greenwashing — misleading environmental claims. Key debate: Does voluntary CSR work? Or is binding regulation needed? Key legal trend: Duty of care (Sorgfaltspflicht) — France loi de vigilance (2017), Germany Lieferkettensorgfaltspflichtengesetz (2023). Dax 40 companies: ESG scoring. Shared value (Porter and Kramer) — business can create economic AND social value simultaneously. Purpose economy (Patagonia — company donates profits to environmental causes)."},"examples":[{"german":"Unternehmensverantwortung hat sich von einer freiwilligen Reputationsstrategie zu einer regulierten Pflicht entwickelt: Während CSR der ersten Generation auf image-wirksame Spenden und Sponsoring setzte, verpflichtet die neuere europäische Gesetzgebung Unternehmen dazu, Nachhaltigkeitsrisiken systematisch zu erfassen, zu steuern und öffentlich zu berichten.","english":"Corporate responsibility has developed from a voluntary reputation strategy into a regulated obligation: while CSR of the first generation relied on image-effective donations and sponsoring, the newer European legislation obliges companies to systematically capture, manage, and publicly report sustainability risks."},{"german":"Die Kritik am ESG-Ansatz trifft einen wunden Punkt: Wenn Unternehmen ESG-Kriterien als Marketinginstrument instrumentalisieren, ohne ihre Geschäftsmodelle grundlegend zu transformieren, bleibt Nachhaltigkeit eine Fassade. Strukturell wirkungsvolle Unternehmensverantwortung erfordert die Integration von Umwelt- und Sozialzielen in Kernstrategie und Kapitalallokation — nicht in deren Beiwerk.","english":"The critique of the ESG approach hits a sore point: if companies instrumentalise ESG criteria as a marketing instrument without fundamentally transforming their business models, sustainability remains a façade. Structurally effective corporate responsibility requires the integration of environmental and social goals into core strategy and capital allocation — not into their accessories."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss CSR evolution, ESG criticism, and Germany''s corporate governance at B2."}}',
'{"items":[{"word":"freiwillig","translation":"voluntary","pronunciation":"FRY-vi-likh","example":"Freiwillige Verantwortung."},{"word":"erfassen","translation":"to capture/record","pronunciation":"er-FAS-en","example":"Risiken erfassen."},{"word":"instrumentalisieren","translation":"to instrumentalise","pronunciation":"in-stru-men-tah-li-ZEE-ren","example":"Als Instrument nutzen."},{"word":"die Fassade","translation":"façade","pronunciation":"dee fa-SAH-deh","example":"Nachhaltigkeitsfassade."},{"word":"die Kapitalallokation","translation":"capital allocation","pronunciation":"dee ka-pi-TAHL-ah-lo-kah-tsyohn","example":"Kapitalallokation ändern."},{"word":"das Beiwerk","translation":"accessories/peripheral elements","pronunciation":"dahs BY-verk","example":"Nicht im Beiwerk."}]}',
'{"title":"X einen wunden Punkt treffen — to hit a sore point of X (identifying a genuine vulnerability)","pattern":"die Kritik trifft einen wunden Punkt = the critique hits a sore point (einen wunden Punkt treffen = to hit a sore spot — idiom: wund = sore/wounded, Punkt = point; marks that criticism has hit a real, acknowledged vulnerability)","explanation":"Einen wunden Punkt treffen = to hit a sore point (idiom — wund = wounded/sore; Punkt = point). Die Kritik am ESG-Ansatz trifft einen wunden Punkt = The critique of the ESG approach hits a sore point. The phrase acknowledges that a criticism is valid and targets a real weakness — it''s not dismissing the critique, but conceding its force. Often used to introduce a concession before offering a counterargument. Compare: ins Schwarze treffen (to hit the bullseye — more positive accurate hit), auf einen Schwachpunkt hinweisen (to point to a weak point — more neutral), berechtigt sein (to be justified — simpler), einen Nerv treffen (to hit a nerve — more emotional/personal).","examples":[{"sentence":"Diese Frage trifft einen wunden Punkt unserer Planungsstrategie.","translation":"This question hits a sore point of our planning strategy."},{"sentence":"Die Kritik trifft einen wunden Punkt des Systems.","translation":"The criticism hits a sore point of the system."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Instrumentalisieren'' means?","options":["to instrumentalise","to exploit","to misuse","to co-opt"],"correctAnswer":"to instrumentalise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Corporate responsibility has developed from a voluntary reputation strategy into a regulated obligation: while CSR of the first generation relied on image-effective donations and sponsoring, the newer European legislation obliges companies to systematically capture, manage, and publicly report sustainability risks.","options":["Unternehmensverantwortung hat sich von einer freiwilligen Reputationsstrategie zu einer regulierten Pflicht entwickelt: Während CSR der ersten Generation auf image-wirksame Spenden und Sponsoring setzte, verpflichtet die neuere europäische Gesetzgebung Unternehmen dazu, Nachhaltigkeitsrisiken systematisch zu erfassen, zu steuern und öffentlich zu berichten.","CSR ist von freiwillig zu verpflichtend geworden.","Europäische Regulierung zwingt Unternehmen zu mehr Transparenz bei Nachhaltigkeitsrisiken.","Nachhaltigkeitsberichte sind von einer PR-Maßnahme zu einer Rechtspflicht geworden."],"correctAnswer":"Unternehmensverantwortung hat sich von einer freiwilligen Reputationsstrategie zu einer regulierten Pflicht entwickelt: Während CSR der ersten Generation auf image-wirksame Spenden und Sponsoring setzte, verpflichtet die neuere europäische Gesetzgebung Unternehmen dazu, Nachhaltigkeitsrisiken systematisch zu erfassen, zu steuern und öffentlich zu berichten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Frage trifft einen wunden Punkt unserer ___.","options":["Planungsstrategie","Strategie","Planung","Konzeption"],"correctAnswer":"Planungsstrategie"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The criticism hits a sore point of the system","wordBankItems":["Die","Kritik","trifft","einen","wunden","Punkt","des","Systems","."],"correctAnswer":"Die Kritik trifft einen wunden Punkt des Systems ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Beiwerk'' means?","options":["accessories/peripheral elements","extras","additions","supplementary items"],"correctAnswer":"accessories/peripheral elements"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002dd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss finance and speculation at B2","Use Finanzwirtschaft und Spekulation vocabulary","Talk about the financial crisis, speculation, and financial regulation in Germany"],"explanation":{"intro":"Finance and speculation vocabulary covers the 2008 financial crisis, financial regulation, and Germany''s approach to financial markets at B2.","culturalNote":"Finanzwirtschaft und Spekulation: Germany: Sparkassen (savings banks — local, not profit-maximising — 370 institutions), Volksbanken (cooperative banks — 800), Deutsche Bank (global investment bank — scandals). Key event: Finanzkrise 2008/09 (financial crisis — Lehman Brothers — subprime mortgage crisis — Germany: €500bn bank bailout). Key concept: Finanzspekulation (financial speculation), Leerverkäufe (short-selling), Hebelfinanzierung (leveraged finance — Leverage). Too big to fail. Systemrelevanz (systemic relevance). Key regulation: Basel III (bank capital requirements), EU Financial Stability Regulation, Hochfrequenzhandel (high-frequency trading). Tobin Tax (Finanztransaktionssteuer — long debated in EU — finally partial agreement). Key figure: Hyman Minsky (financial instability hypothesis — stability is destabilising)."},"examples":[{"german":"Die Finanzkrise von 2008 hat einen zentralen Konstruktionsfehler moderner Finanzmärkte freigelegt: Wenn die Stabilität einzelner Akteure systemische Relevanz erlangt, ist der Markt kein selbstregulierender Mechanismus mehr, sondern ein politisch verwaltetes Risiko — der Staat muss einspringen, weil er das Scheitern der systemrelevanten Institute nicht zulassen kann.","english":"The financial crisis of 2008 revealed a central design flaw of modern financial markets: when the stability of individual actors acquires systemic relevance, the market is no longer a self-regulating mechanism, but a politically managed risk — the state must step in because it cannot allow the failure of systemically relevant institutions."},{"german":"Finanzspekulation ist nicht per se unethisch, aber unregulierte Spekulation erzeugt exteriorisierte Risiken: Wenn Gewinne privatisiert und Verluste sozialisiert werden — wie in der Krise von 2008 — bricht der Mechanismus marktlicher Haftung zusammen, der Fehlanreize für exzessives Risikoverhalten verhindern soll.","english":"Financial speculation is not per se unethical, but unregulated speculation generates externalised risks: when profits are privatised and losses socialised — as in the 2008 crisis — the mechanism of market liability breaks down, which is supposed to prevent false incentives for excessive risk behaviour."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the 2008 financial crisis, systemic risk, and the too-big-to-fail problem at B2."}}',
'{"items":[{"word":"freilegen","translation":"to reveal/expose","pronunciation":"FRY-lay-gen","example":"Fehler freilegen."},{"word":"der Konstruktionsfehler","translation":"design flaw","pronunciation":"dayr kon-strook-TSYOHNS-fay-ler","example":"Zentraler Konstruktionsfehler."},{"word":"einspringen","translation":"to step in","pronunciation":"YN-shpring-en","example":"Der Staat muss einspringen."},{"word":"exteriorisiert","translation":"externalised","pronunciation":"eks-teh-ryoh-ri-ZEERT","example":"Exteriorisierte Risiken."},{"word":"privatisiert","translation":"privatised","pronunciation":"pri-vah-ti-ZEERT","example":"Gewinne privatisiert."},{"word":"der Fehlanreiz","translation":"false incentive","pronunciation":"dayr FAL-an-ryts","example":"Fehlanreize verhindern."}]}',
'{"title":"Gewinne privatisieren und Verluste sozialisieren — privatising profits and socialising losses","pattern":"Gewinne werden privatisiert und Verluste sozialisiert = profits are privatised and losses are socialised (passives: privatisiert/sozialisiert — past participles used as predicates; the phrase captures a structural asymmetry in risk distribution)","explanation":"Gewinne privatisieren (to privatise profits — accrues to private actors) vs. Verluste sozialisieren (to socialise losses — spread across the public). This paired phrase captures a structural asymmetry: the upside goes private, the downside is shared publicly. When Gewinne privatisiert und Verluste sozialisiert werden = when profits are privatised and losses are socialised (passive). The phrase is a powerful critical formulation in political economy, applicable to banking bailouts, privatisation debates, and corporate-state relations. Compare: Risiko auf andere abwälzen (to offload risk onto others), moral hazard (Fehlanreiz — creates reckless risk-taking), Vergemeinschaftung von Verlusten (communalisation of losses).","examples":[{"sentence":"In diesem System werden Gewinne privatisiert und Verluste sozialisiert.","translation":"In this system, profits are privatised and losses are socialised."},{"sentence":"Das Prinzip lautet: Gewinne privatisieren, Verluste der Allgemeinheit aufbürden.","translation":"The principle is: privatise profits, burden the public with losses."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Freilegen'' means?","options":["to reveal/expose","to uncover","to lay bare","to disclose"],"correctAnswer":"to reveal/expose"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The financial crisis of 2008 revealed a central design flaw of modern financial markets: when the stability of individual actors acquires systemic relevance, the market is no longer a self-regulating mechanism, but a politically managed risk — the state must step in because it cannot allow the failure of systemically relevant institutions.","options":["Die Finanzkrise von 2008 hat einen zentralen Konstruktionsfehler moderner Finanzmärkte freigelegt: Wenn die Stabilität einzelner Akteure systemische Relevanz erlangt, ist der Markt kein selbstregulierender Mechanismus mehr, sondern ein politisch verwaltetes Risiko — der Staat muss einspringen, weil er das Scheitern der systemrelevanten Institute nicht zulassen kann.","Die Finanzkrise 2008 zeigte, dass Finanzmärkte sich nicht selbst regulieren können.","Systemrelevante Banken müssen gerettet werden, auch wenn sie Fehler gemacht haben.","Too-big-to-fail macht Finanzmärkte politisch abhängig."],"correctAnswer":"Die Finanzkrise von 2008 hat einen zentralen Konstruktionsfehler moderner Finanzmärkte freigelegt: Wenn die Stabilität einzelner Akteure systemische Relevanz erlangt, ist der Markt kein selbstregulierender Mechanismus mehr, sondern ein politisch verwaltetes Risiko — der Staat muss einspringen, weil er das Scheitern der systemrelevanten Institute nicht zulassen kann."},{"id":"ex3","type":"FILL_IN_BLANK","question":"In diesem System werden Gewinne privatisiert und Verluste ___.","options":["sozialisiert","vergemeinschaftet","verteilt","geteilt"],"correctAnswer":"sozialisiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The principle is privatise profits burden the public with losses","wordBankItems":["Das","Prinzip","lautet",":","Gewinne","privatisieren",",","Verluste","der","Allgemeinheit","aufbürden","."],"correctAnswer":"Das Prinzip lautet : Gewinne privatisieren , Verluste der Allgemeinheit aufbürden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Fehlanreiz'' means?","options":["false incentive","wrong incentive","misaligned incentive","perverse incentive"],"correctAnswer":"false incentive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002de',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss world economy and trade policy at B2","Use Weltwirtschaft und Handelspolitik vocabulary","Talk about WTO, free trade debates, and Germany''s export-oriented economy"],"explanation":{"intro":"World economy and trade policy vocabulary covers Germany''s export model, WTO, and international trade debates at B2.","culturalNote":"Weltwirtschaft und Handelspolitik: Germany: weltgrößter Exporteur #3 (nach USA, China) — Exportweltmeister (export world champion — a pride and a liability). Key: Leistungsbilanzüberschuss (current account surplus — Germany persistently 7-8% GDP — IMF/EU criticism — rebalancing debate). Exportorientierte Wirtschaft (export-oriented economy). WTO (World Trade Organisation — 164 members — dispute settlement). GATT → WTO (1995). Protektionismus (protectionism — Trump tariffs 2018). Freihandelsabkommen (free trade agreement): TTIP (failed), CETA (EU-Canada), EU-Mercosur. Key concept: komparativer Vorteil (comparative advantage — Ricardo). Dumping (exporting below cost). Neue Seidenstraße (Belt and Road Initiative — China). Lieferkettendiversifizierung (supply chain diversification — post-COVID — de-risking from China)."},"examples":[{"german":"Deutschlands persistente Leistungsbilanzüberschüsse sind makroökonomisch ambivalent: Sie spiegeln die Wettbewerbsstärke des Exportsektors wider, signalisieren aber zugleich eine schwache Binnennachfrage und Unterinvestition in Infrastruktur — ein Ungleichgewicht, das die wirtschaftliche Stabilität des Euroraums belasten kann, wenn Überschussländer nicht nachfragend stimuliert werden.","english":"Germany''s persistent current account surpluses are macroeconomically ambivalent: they reflect the competitive strength of the export sector, but simultaneously signal weak domestic demand and underinvestment in infrastructure — an imbalance that can burden the economic stability of the eurozone if surplus countries are not demand-stimulated."},{"german":"Freihandel produziert Gewinner und Verlierer: Auf aggregierter volkswirtschaftlicher Ebene erhöht er Wohlstand durch Spezialisierung und Skaleneffekte; auf disaggregierter Ebene zerstört er Branchen und Regionen, die nicht wettbewerbsfähig sind — eine Verteilungsspannung, die durch Kompensationsmechanismen abzumildern ist, wenn politische Stabilität gewahrt bleiben soll.","english":"Free trade produces winners and losers: at the aggregate macroeconomic level, it increases prosperity through specialisation and scale effects; at the disaggregated level, it destroys sectors and regions that are not competitive — a distributional tension that must be mitigated by compensation mechanisms if political stability is to be maintained."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s export surplus, free trade debates, and WTO at B2."}}',
'{"items":[{"word":"der Überschuss","translation":"surplus","pronunciation":"dayr Ü-ber-shooss","example":"Leistungsbilanzüberschuss."},{"word":"ambivalent","translation":"ambivalent","pronunciation":"am-bi-vah-LENT","example":"Makroökonomisch ambivalent."},{"word":"die Binnennachfrage","translation":"domestic demand","pronunciation":"dee BIN-en-nakh-frah-geh","example":"Schwache Binnennachfrage."},{"word":"disaggregiert","translation":"disaggregated","pronunciation":"dis-ah-greh-GEERT","example":"Disaggregierte Ebene."},{"word":"die Skaleneffekte","translation":"scale effects","pronunciation":"dee SKAH-len-ef-ek-teh","example":"Spezialisierung und Skaleneffekte."},{"word":"abmildern","translation":"to mitigate","pronunciation":"AB-mil-dern","example":"Spannungen abmildern."}]}',
'{"title":"Auf aggregierter Ebene X; auf disaggregierter Ebene Y — at aggregate level X; at disaggregated level Y","pattern":"auf aggregierter/disaggregierter Ebene = at the aggregate/disaggregated level (macro/micro decomposition pattern — the same phenomenon looks different depending on the level of analysis: aggregate benefits can coexist with distributional harms)","explanation":"Aggregiert = aggregated (total, combined — macroeconomic level). Disaggregiert = disaggregated (broken down by individual units — distributional level). Auf aggregierter volkswirtschaftlicher Ebene erhöht Freihandel Wohlstand; auf disaggregierter Ebene zerstört er Branchen = At the aggregate macroeconomic level, free trade increases prosperity; at the disaggregated level, it destroys sectors. The pattern is used to show that aggregate statistics can conceal distributional effects: overall gain + concentrated losses. Compare: im Durchschnitt vs. im Einzelfall (on average vs. in individual cases), gesamtwirtschaftlich vs. sektoral (economy-wide vs. sector-specific), im Großen und Ganzen vs. im Detail (broadly vs. in detail).","examples":[{"sentence":"Auf aggregierter Ebene wächst die Wirtschaft; auf disaggregierter Ebene verlieren bestimmte Regionen.","translation":"At the aggregate level, the economy grows; at the disaggregated level, certain regions lose."},{"sentence":"Gesamtwirtschaftlich erhöht Automatisierung den Wohlstand; auf Branchenebene vernichtet sie Arbeitsplätze.","translation":"Economy-wide, automation increases prosperity; at the sector level, it destroys jobs."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ambivalent'' means?","options":["ambivalent","equivocal","mixed","uncertain"],"correctAnswer":"ambivalent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Free trade produces winners and losers: at the aggregate macroeconomic level, it increases prosperity through specialisation and scale effects; at the disaggregated level, it destroys sectors and regions that are not competitive — a distributional tension that must be mitigated by compensation mechanisms if political stability is to be maintained.","options":["Freihandel produziert Gewinner und Verlierer: Auf aggregierter volkswirtschaftlicher Ebene erhöht er Wohlstand durch Spezialisierung und Skaleneffekte; auf disaggregierter Ebene zerstört er Branchen und Regionen, die nicht wettbewerbsfähig sind — eine Verteilungsspannung, die durch Kompensationsmechanismen abzumildern ist, wenn politische Stabilität gewahrt bleiben soll.","Freihandel nützt der Wirtschaft insgesamt, schadet aber bestimmten Branchen.","Der Wohlstandsgewinn durch Freihandel verdeckt seine Verlierer.","Freihandel braucht Begleitung durch Sozialpolitik, um politisch stabil zu bleiben."],"correctAnswer":"Freihandel produziert Gewinner und Verlierer: Auf aggregierter volkswirtschaftlicher Ebene erhöht er Wohlstand durch Spezialisierung und Skaleneffekte; auf disaggregierter Ebene zerstört er Branchen und Regionen, die nicht wettbewerbsfähig sind — eine Verteilungsspannung, die durch Kompensationsmechanismen abzumildern ist, wenn politische Stabilität gewahrt bleiben soll."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Auf aggregierter Ebene wächst die Wirtschaft; auf disaggregierter Ebene ___ bestimmte Regionen.","options":["verlieren","schrumpfen","stagnieren","leiden"],"correctAnswer":"verlieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Economy-wide automation increases prosperity at the sector level it destroys jobs","wordBankItems":["Gesamtwirtschaftlich","erhöht","Automatisierung","den","Wohlstand",";","auf","Branchenebene","vernichtet","sie","Arbeitsplätze","."],"correctAnswer":"Gesamtwirtschaftlich erhöht Automatisierung den Wohlstand ; auf Branchenebene vernichtet sie Arbeitsplätze ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Abmildern'' means?","options":["to mitigate","to soften","to reduce","to diminish"],"correctAnswer":"to mitigate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002df',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss raw materials and resource policy at B2","Use Rohstoffe und Ressourcenpolitik vocabulary","Talk about resource dependency, critical minerals, and Germany''s supply chain challenges"],"explanation":{"intro":"Raw materials and resource policy vocabulary covers critical mineral dependencies, resource geopolitics, and Germany''s supply chain challenges at B2.","culturalNote":"Rohstoffe und Ressourcenpolitik: Germany: hochgradig ressourcenabhängig (highly resource-dependent) — imports 100% of lithium, cobalt, rare earths needed for energy transition. Key concept: Kritische Rohstoffe (critical raw materials — EU list — 34 materials — cobalt, lithium, rare earths, silicon, platinum group metals). China: dominates 60%+ of rare earth supply. Resource curse (Ressourcenfluch — paradox of plenty — countries rich in resources often develop poorly — Dutch disease). OPEC (oil cartel). LNG (liquefied natural gas — Germany built LNG terminals in 2022 after Russia gas cut-off). Key: Energy transition needs 6× more minerals than current energy systems. German raw materials strategy (Rohstoffstrategie — diversification, recycling, substitution). Urban mining (recovering materials from electronic waste — e-waste)."},"examples":[{"german":"Die Energiewende ist eine ressourcenpolitische Herausforderung eigener Art: Sie löst die Abhängigkeit von fossilen Brennstoffen durch Abhängigkeit von Metallen und Mineralien — Lithium, Kobalt, Neodym — die geografisch konzentriert und geopolitisch umkämpft sind. Eine Dekarbonisierungsstrategie, die diese Abhängigkeiten ignoriert, löst ein geopolitisches Problem durch ein anderes.","english":"The energy transition is a resource policy challenge of its own kind: it resolves the dependence on fossil fuels through dependence on metals and minerals — lithium, cobalt, neodymium — that are geographically concentrated and geopolitically contested. A decarbonisation strategy that ignores these dependencies resolves one geopolitical problem through another."},{"german":"Der Ressourcenfluch bezeichnet ein paradoxes Entwicklungsphänomen: Länder mit großem Rohstoffreichtum weisen oft schlechtere wirtschaftliche und politische Entwicklung auf als ressourcenarme Länder — weil Rohstoffeinnahmen Eliten bereichern, Institutionen schwächen, die eigene Industrie durch überbewertete Wechselkurse verdrängen und demokratische Kontrolle unterminieren.","english":"The resource curse designates a paradoxical development phenomenon: countries with great natural resource wealth often show worse economic and political development than resource-poor countries — because natural resource revenues enrich elites, weaken institutions, displace domestic industry through overvalued exchange rates, and undermine democratic control."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss critical minerals, the resource curse, and Germany''s supply chain challenges at B2."}}',
'{"items":[{"word":"umkämpft","translation":"contested","pronunciation":"oom-KEMPFT","example":"Geopolitisch umkämpft."},{"word":"die Dekarbonisierung","translation":"decarbonisation","pronunciation":"dee deh-kar-bo-ni-ZEE-roong","example":"Dekarbonisierungsstrategie."},{"word":"ressourcenarm","translation":"resource-poor","pronunciation":"reh-SOOR-tsen-arm","example":"Ressourcenarme Länder."},{"word":"überbewerten","translation":"to overvalue","pronunciation":"ü-ber-beh-VER-ten","example":"Wechselkurse überbewerten."},{"word":"unterminieren","translation":"to undermine","pronunciation":"oon-ter-mi-NEE-ren","example":"Demokratie unterminieren."},{"word":"der Reichtum","translation":"wealth/richness","pronunciation":"dayr RYKH-toom","example":"Rohstoffreichtum."}]}',
'{"title":"X löst Y durch Z — X resolves Y through Z (substitution of one problem for another)","pattern":"etwas löst X durch Y = something resolves X through Y (lösen = to resolve/solve; durch = through/by means of Y — marks the substitution; often used critically when the ''solution'' creates a new version of the problem)","explanation":"Lösen durch = to resolve through/by means of (lösen = to solve, resolve — durch + accusative marks the means). Eine Strategie, die X durch Y löst = a strategy that resolves X through Y. When used critically: the ''solution'' merely substitutes one problem (X) for another (Y) of the same type. Ein geopolitisches Problem durch ein anderes lösen = resolving one geopolitical problem through another. The pattern is transferable to any domain where a proposed solution creates new problems of the same kind. Compare: X ersetzen durch Y (to replace X with Y — more neutral substitution), aus einer Abhängigkeit in eine andere geraten (to fall from one dependency into another — more descriptive), one step forward, one step back (more informal).","examples":[{"sentence":"Wir lösen das Energieproblem nicht dadurch, dass wir eine Abhängigkeit durch eine andere ersetzen.","translation":"We don''t solve the energy problem by replacing one dependency with another."},{"sentence":"Den Datenschutzmangel durch Zentralisierung zu lösen, schafft ein anderes Problem.","translation":"Resolving the data protection gap through centralisation creates a different problem."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unterminieren'' means?","options":["to undermine","to subvert","to erode","to weaken"],"correctAnswer":"to undermine"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The energy transition is a resource policy challenge of its own kind: it resolves the dependence on fossil fuels through dependence on metals and minerals — lithium, cobalt, neodymium — that are geographically concentrated and geopolitically contested. A decarbonisation strategy that ignores these dependencies resolves one geopolitical problem through another.","options":["Die Energiewende ist eine ressourcenpolitische Herausforderung eigener Art: Sie löst die Abhängigkeit von fossilen Brennstoffen durch Abhängigkeit von Metallen und Mineralien — Lithium, Kobalt, Neodym — die geografisch konzentriert und geopolitisch umkämpft sind. Eine Dekarbonisierungsstrategie, die diese Abhängigkeiten ignoriert, löst ein geopolitisches Problem durch ein anderes.","Die Energiewende schafft neue Rohstoffabhängigkeiten statt die alten zu beseitigen.","Lithium und Kobalt für Batterien sind genauso geopolitisch heikel wie Öl und Gas.","Die Energiewende verlagert Abhängigkeiten, löst sie aber nicht grundlegend."],"correctAnswer":"Die Energiewende ist eine ressourcenpolitische Herausforderung eigener Art: Sie löst die Abhängigkeit von fossilen Brennstoffen durch Abhängigkeit von Metallen und Mineralien — Lithium, Kobalt, Neodym — die geografisch konzentriert und geopolitisch umkämpft sind. Eine Dekarbonisierungsstrategie, die diese Abhängigkeiten ignoriert, löst ein geopolitisches Problem durch ein anderes."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir lösen das Energieproblem nicht dadurch, dass wir eine Abhängigkeit durch eine andere ___.","options":["ersetzen","lösen","tauschen","substituieren"],"correctAnswer":"ersetzen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Resolving the data protection gap through centralisation creates a different problem","wordBankItems":["Den","Datenschutzmangel","durch","Zentralisierung","zu","lösen",",","schafft","ein","anderes","Problem","."],"correctAnswer":"Den Datenschutzmangel durch Zentralisierung zu lösen , schafft ein anderes Problem ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Umkämpft'' means?","options":["contested","disputed","fought over","competitive"],"correctAnswer":"contested"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss agricultural economy and food at B2","Use Agrarwirtschaft und Ernährung vocabulary","Talk about German agriculture, food security, and sustainable farming debates"],"explanation":{"intro":"Agricultural economy and food vocabulary covers German agriculture, food security, and sustainable farming debates at B2.","culturalNote":"Agrarwirtschaft und Ernährung: Germany: 262,000 farms (2020) — average 61ha — structural change (Höfesterben — farm dying). Key tension: Industrielle Landwirtschaft (industrial agriculture — efficiency, pesticides, monoculture) vs. Ökologische Landwirtschaft (organic farming — 10.5% German farmland — highest in EU). Subventionen (EU agricultural subsidies — CAP — €6bn/year to Germany). Tierhaltung (livestock — factory farming — Tierschutzgesetz — debate). Lebensmittelverschwendung (food waste — 11 million tonnes/year Germany). Food sovereignty. Ackerland-Finanzierung (farmland as investment — hedge funds buying farmland). Key debates: glyphosate (Glyphosat) ban, Insektensterben (insect death — neonicotinoids). Bauernproteste (farmers'' protests — 2024 — against diesel subsidy cuts). Agrarökologie (agroecology — alternative to industrial farming)."},"examples":[{"german":"Das deutsche Agrarsystem befindet sich in einer Transformationskrise: Die konventionelle Landwirtschaft steht unter wirtschaftlichem Druck durch steigende Betriebskosten und sinkende Erzeugerpreise, während gesellschaftliche Erwartungen an Tierschutz, Umweltqualität und Biodiversitätsschutz zunehmen — ein Widerspruch, den subventionspolitische Instrumente allein nicht auflösen.","english":"The German agricultural system finds itself in a transformation crisis: conventional agriculture is under economic pressure from rising operating costs and falling producer prices, while social expectations about animal welfare, environmental quality, and biodiversity protection increase — a contradiction that subsidy policy instruments alone cannot resolve."},{"german":"Ernährungssouveränität ist eine Frage der politischen Ökonomie, keine bloß technische: Sie fragt, wer die Bedingungen des Nahrungsmittelanbaus bestimmt, wer von der Wertschöpfung profitiert und wer das Recht hat, Ernährungssysteme demokratisch zu gestalten — Fragen, die durch die Konzentration von Marktmacht in Handelskonzernen und Saatgutmonopolen zunehmend unter Druck geraten.","english":"Food sovereignty is a question of political economy, not merely technical: it asks who determines the conditions of food cultivation, who profits from the added value, and who has the right to democratically shape food systems — questions that come under increasing pressure through the concentration of market power in retail corporations and seed monopolies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s agricultural crisis, food sovereignty, and organic farming debate at B2."}}',
'{"items":[{"word":"der Erzeugerpreis","translation":"producer price","pronunciation":"dayr er-TSOY-ger-prys","example":"Sinkende Erzeugerpreise."},{"word":"der Betriebskosten","translation":"operating costs","pronunciation":"dayr beh-TREEPS-kos-ten","example":"Steigende Betriebskosten."},{"word":"der Saatgut","translation":"seeds","pronunciation":"dayr ZAHT-goot","example":"Saatgutmonopole."},{"word":"die Souveränität","translation":"sovereignty","pronunciation":"dee zo-veh-rä-ni-TÄT","example":"Ernährungssouveränität."},{"word":"anbauen","translation":"to cultivate/grow","pronunciation":"AN-bow-en","example":"Nahrungsmittel anbauen."},{"word":"gestalten","translation":"to shape","pronunciation":"geh-SHTAL-ten","example":"Systeme gestalten."}]}',
'{"title":"Nicht bloß technisch, sondern eine Frage der politischen Ökonomie — not merely technical but a question of political economy","pattern":"X ist keine bloß technische Frage, sondern eine der politischen Ökonomie = X is not merely a technical question, but one of political economy (bloß = merely/only; keine...Frage = not a...question; sondern eine der... = but one of... — implicit Frage dropped)","explanation":"Keine bloß technische Frage = not a merely technical question (bloß = only, merely — limits and dismisses the technical characterisation). Sondern eine der politischen Ökonomie = but one of political economy (eine [Frage] der... — genitive: ellipsis of Frage after sondern eine). The pattern elevates the stakes: what appears to be a technical problem (efficiency, optimisation) is actually a political and economic one (power, distribution, rights). Widely used in critical social science. Compare: nicht nur..., sondern auch (not only..., but also — additive), nicht technisch, sondern normativ (not technical, but normative), eine politische Entscheidung, keine fachliche (a political decision, not a technical one).","examples":[{"sentence":"Stadtplanung ist keine bloß ästhetische Frage, sondern eine der politischen Ökonomie.","translation":"Urban planning is not merely an aesthetic question, but one of political economy."},{"sentence":"Migration ist keine bloß humanitäre Frage, sondern eine der Verteilungspolitik.","translation":"Migration is not merely a humanitarian question, but one of distributive politics."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Erzeugerpreis'' means?","options":["producer price","farm gate price","wholesale price","production price"],"correctAnswer":"producer price"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Food sovereignty is a question of political economy, not merely technical: it asks who determines the conditions of food cultivation, who profits from the added value, and who has the right to democratically shape food systems — questions that come under increasing pressure through the concentration of market power in retail corporations and seed monopolies.","options":["Ernährungssouveränität ist eine Frage der politischen Ökonomie, keine bloß technische: Sie fragt, wer die Bedingungen des Nahrungsmittelanbaus bestimmt, wer von der Wertschöpfung profitiert und wer das Recht hat, Ernährungssysteme demokratisch zu gestalten — Fragen, die durch die Konzentration von Marktmacht in Handelskonzernen und Saatgutmonopolen zunehmend unter Druck geraten.","Ernährungssouveränität bedeutet, dass Bauern selbst über Anbaubedingungen entscheiden.","Marktmacht von Supermarktketten und Saatgutkonzernen bedroht die Ernährungssouveränität.","Wer Saatgut und Handel kontrolliert, kontrolliert das Ernährungssystem."],"correctAnswer":"Ernährungssouveränität ist eine Frage der politischen Ökonomie, keine bloß technische: Sie fragt, wer die Bedingungen des Nahrungsmittelanbaus bestimmt, wer von der Wertschöpfung profitiert und wer das Recht hat, Ernährungssysteme demokratisch zu gestalten — Fragen, die durch die Konzentration von Marktmacht in Handelskonzernen und Saatgutmonopolen zunehmend unter Druck geraten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Stadtplanung ist keine bloß ästhetische Frage, sondern eine der ___.","options":["politischen Ökonomie","Stadtpolitik","Wirtschaftspolitik","Sozialpolitik"],"correctAnswer":"politischen Ökonomie"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Migration is not merely a humanitarian question but one of distributive politics","wordBankItems":["Migration","ist","keine","bloß","humanitäre","Frage",",","sondern","eine","der","Verteilungspolitik","."],"correctAnswer":"Migration ist keine bloß humanitäre Frage , sondern eine der Verteilungspolitik ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anbauen'' means?","options":["to cultivate/grow","to plant","to farm","to produce"],"correctAnswer":"to cultivate/grow"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss economic growth and its limits at B2","Use Wirtschaftswachstum und seine Grenzen vocabulary","Talk about degrowth, post-growth economics, and Germany''s relationship with GDP"],"explanation":{"intro":"Economic growth and its limits vocabulary covers degrowth theory, post-growth economics, and Germany''s Wachstumsparadigma at B2.","culturalNote":"Wirtschaftswachstum und seine Grenzen: Key: ''Grenzen des Wachstums'' (Limits to Growth — Club of Rome — 1972 — Meadows — computer simulation — overshoot scenario). Steady-state economics (Herman Daly). Degrowth / Post-Wachstum (degrowth — Serge Latouche, Tim Jackson ''Prosperity without Growth'' — 2009). Germany: Wachstumsorientierung (growth orientation) of Wirtschaftspolitik challenged. GDP vs. BIP alternatives: HDI (Human Development Index), Genuine Progress Indicator, Doughnut Economics (Kate Raworth). Grüne Wachstumspolitik (green growth — decoupling argument: can GDP grow while resource use falls? — empirical debate). Wachstumskritik: Does GDP growth still increase wellbeing in rich societies? (Easterlin Paradox again). Key German debate: Degrowth conference Leipzig (2014 — 3,000 participants — major degrowth conference)."},"examples":[{"german":"Die Debatte um Wachstumsgrenzen ist eine der grundlegendsten wirtschaftspolitischen Kontroversen: Sie stellt die Frage, ob ein ökologisch verträgliches Wirtschaften mit dem Wachstumsparadigma vereinbar ist oder ob Wohlstand auf einem Niveau erreicht werden kann, das ohne kontinuierliche Expansion auskommt — eine Frage, die nicht nur wirtschaftlich, sondern auch politisch und ethisch kontrovers ist.","english":"The debate about limits to growth is one of the most fundamental economic policy controversies: it poses the question of whether an ecologically compatible economy is reconcilable with the growth paradigm, or whether prosperity can be achieved at a level that manages without continuous expansion — a question that is controversial not only economically, but also politically and ethically."},{"german":"Degrowth ist keine Schrumpfungsstrategie, sondern ein Transformationskonzept: Es zielt auf eine gesellschaftliche Neuausrichtung, in der Prosperität nicht an BIP-Wachstum gekoppelt ist, sondern an Qualität menschlicher Beziehungen, ökologischer Integrität und demokratischer Selbstbestimmung — eine Umwertung, die mit etablierten Wirtschaftsinteressen und institutionellen Pfadabhängigkeiten kollidiert.","english":"Degrowth is not a shrinkage strategy, but a transformation concept: it aims at a societal reorientation in which prosperity is not coupled to GDP growth, but to the quality of human relations, ecological integrity, and democratic self-determination — a revaluation that collides with established economic interests and institutional path dependencies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss degrowth theory, limits to growth, and post-growth economics at B2."}}',
'{"items":[{"word":"verträglich","translation":"compatible/tolerable","pronunciation":"fer-TREG-likh","example":"Ökologisch verträglich."},{"word":"auskommen ohne","translation":"to manage without","pronunciation":"OWS-ko-men OH-neh","example":"Ohne Wachstum auskommen."},{"word":"die Schrumpfung","translation":"shrinkage","pronunciation":"dee SHROOMP-foong","example":"Keine Schrumpfungsstrategie."},{"word":"koppeln an","translation":"to couple to","pronunciation":"KOP-eln an","example":"An BIP koppeln."},{"word":"kollidieren mit","translation":"to collide with","pronunciation":"ko-li-DEE-ren mit","example":"Mit Interessen kollidieren."},{"word":"die Pfadabhängigkeit","translation":"path dependency","pronunciation":"dee PFAD-ab-heng-ikh-kyt","example":"Institutionelle Pfadabhängigkeit."}]}',
'{"title":"X an Y koppeln vs. X von Y entkoppeln — coupling X to Y vs. decoupling X from Y","pattern":"X an Y koppeln = to couple X to Y (koppeln an + accusative — link X so that X depends on/tracks Y); X von Y entkoppeln = to decouple X from Y (entkoppeln = to decouple/uncouple — removes the link between X and Y)","explanation":"Koppeln an = to couple to (link/make dependent on). Entkoppeln von = to decouple from (unlink). Prosperität an BIP-Wachstum gekoppelt = prosperity coupled to GDP growth. Koppeln implies the two things move together; entkoppeln means making them independent. Widely used in policy debates: decouple economic growth from resource use, decouple wages from productivity, decouple inflation from interest rates. Grammatically: X an Y koppeln (X = what is coupled; Y = what it is coupled to); passive: X ist an Y gekoppelt (X is coupled to Y). Compare: verknüpfen (to link — general), verbinden mit (to connect with), von X abhängig machen (to make dependent on X).","examples":[{"sentence":"Wir müssen Wirtschaftswachstum von Ressourcenverbrauch entkoppeln.","translation":"We must decouple economic growth from resource consumption."},{"sentence":"Löhne sind historisch an Produktivität gekoppelt.","translation":"Wages are historically coupled to productivity."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verträglich'' means?","options":["compatible/tolerable","sustainable","acceptable","compatible"],"correctAnswer":"compatible/tolerable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Degrowth is not a shrinkage strategy, but a transformation concept: it aims at a societal reorientation in which prosperity is not coupled to GDP growth, but to the quality of human relations, ecological integrity, and democratic self-determination — a revaluation that collides with established economic interests and institutional path dependencies.","options":["Degrowth ist keine Schrumpfungsstrategie, sondern ein Transformationskonzept: Es zielt auf eine gesellschaftliche Neuausrichtung, in der Prosperität nicht an BIP-Wachstum gekoppelt ist, sondern an Qualität menschlicher Beziehungen, ökologischer Integrität und demokratischer Selbstbestimmung — eine Umwertung, die mit etablierten Wirtschaftsinteressen und institutionellen Pfadabhängigkeiten kollidiert.","Degrowth bedeutet nicht Schrumpfung, sondern eine andere Definition von Wohlstand.","Prosperität kann ohne BIP-Wachstum erreicht werden.","Degrowth stellt das Wachstumsparadigma in Frage und trifft auf Widerstand."],"correctAnswer":"Degrowth ist keine Schrumpfungsstrategie, sondern ein Transformationskonzept: Es zielt auf eine gesellschaftliche Neuausrichtung, in der Prosperität nicht an BIP-Wachstum gekoppelt ist, sondern an Qualität menschlicher Beziehungen, ökologischer Integrität und demokratischer Selbstbestimmung — eine Umwertung, die mit etablierten Wirtschaftsinteressen und institutionellen Pfadabhängigkeiten kollidiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir müssen Wirtschaftswachstum von Ressourcenverbrauch ___.","options":["entkoppeln","trennen","lösen","befreien"],"correctAnswer":"entkoppeln"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Wages are historically coupled to productivity","wordBankItems":["Löhne","sind","historisch","an","Produktivität","gekoppelt","."],"correctAnswer":"Löhne sind historisch an Produktivität gekoppelt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Pfadabhängigkeit'' means?","options":["path dependency","path dependence","path lock-in","trajectory dependence"],"correctAnswer":"path dependency"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss state budget and fiscal policy at B2","Use Staatshaushalt und Fiskalpolitik vocabulary","Talk about Germany''s Schuldenbremse, fiscal federalism, and public debt debate"],"explanation":{"intro":"State budget and fiscal policy vocabulary covers Germany''s Schuldenbremse, public investment debate, and fiscal policy at B2.","culturalNote":"Staatshaushalt und Fiskalpolitik: Germany: Schuldenbremse (debt brake — Grundgesetz Art. 109/115 — 2009 — structural deficit limit 0.35% GDP — Länder must have balanced budget — very strict). Key: Schwarze Null (black zero — balanced budget — Ziel des BMF). Critics: investment backlog (Investitionsstau) — €600bn infrastructure gap. COVID exception: Notlagenkredite (emergency borrowing — Bundesverfassungsgericht ruled 2023 that redirecting COVID loans for climate fund unconstitutional — Ampelkoalition crisis). Finanzausgleich (fiscal equalisation — rich Länder subsidise poor ones). Steuerpolitik (tax policy — highest German tax: solidarity surcharge ended 2021 for most). Sparparadoxon (paradox of thrift — Keynes: if everyone saves, recession deepens). Öffentliche Investitionen (public investment) vs. Konsolidierung (fiscal consolidation — austerity)."},"examples":[{"german":"Die Schuldenbremse ist das fiscalpolitische Herzstück des deutschen Konsolidierungskurses: Als Verfassungsgebot limitiert sie strukturelle Defizite auf 0,35% des BIPs und verhindert damit sowohl konjunkturpolitische Flexibilität als auch langfristige öffentliche Investitionen — eine Restriktion, deren Ausgewogenheit zwischen Haushaltsdisziplin und Investitionserfordernissen politisch umstritten bleibt.","english":"The debt brake is the fiscal policy cornerstone of Germany''s consolidation course: as a constitutional requirement, it limits structural deficits to 0.35% of GDP, thereby preventing both cyclical policy flexibility and long-term public investment — a restriction whose balance between fiscal discipline and investment requirements remains politically contested."},{"german":"Öffentliche Investitionen sind keine Ausgaben, sondern Zukunftsinvestitionen: Der Unterschied zwischen konsumtiven Ausgaben und investiven Ausgaben ist ökonomisch fundamental — eine Brücke oder ein Glasfasernetz trägt Jahrzehnte lang zur Produktivität bei, während Transferleistungen sofort konsumiert werden. Eine Haushaltspolitik, die diesen Unterschied ignoriert, behandelt Zukunft und Gegenwart gleich.","english":"Public investments are not expenditures, but investments in the future: the difference between consumptive expenditures and investment expenditures is economically fundamental — a bridge or a fibre network contributes to productivity for decades, while transfer payments are immediately consumed. A budget policy that ignores this difference treats the future and the present as equal."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s debt brake, the investment backlog, and Keynesian fiscal policy at B2."}}',
'{"items":[{"word":"das Herzstück","translation":"cornerstone/centrepiece","pronunciation":"dahs HERTS-shtük","example":"Fiscalpolitisches Herzstück."},{"word":"limitieren","translation":"to limit","pronunciation":"li-mi-TEE-ren","example":"Defizite limitieren."},{"word":"konjunkturpolitisch","translation":"cyclical policy (adj.)","pronunciation":"kon-YOONK-tur-po-li-tish","example":"Konjunkturpolitische Flexibilität."},{"word":"konsumtiv","translation":"consumptive","pronunciation":"kon-zoomp-TEEF","example":"Konsumtive Ausgaben."},{"word":"investiv","translation":"investment (adj.)","pronunciation":"in-ves-TEEF","example":"Investive Ausgaben."},{"word":"der Rückstand","translation":"backlog/lag","pronunciation":"dayr RÜK-shtant","example":"Investitionsrückstand."}]}',
'{"title":"Etwas ist keine Ausgabe, sondern eine Zukunftsinvestition — not an expenditure but an investment in the future","pattern":"X ist keine Ausgabe/kein Verbrauch, sondern eine Investition in die Zukunft = X is not an expenditure/consumption, but an investment in the future (keine...sondern = not...but — reframes from short-term cost to long-term return)","explanation":"Keine Ausgabe, sondern eine Investition = not an expenditure, but an investment. The distinction: Ausgabe/Verbrauch (expenditure/consumption — immediate use, no return) vs. Investition (investment — generates returns over time). Öffentliche Investitionen sind keine Ausgaben, sondern Zukunftsinvestitionen = Public investments are not expenditures, but investments in the future. The reframe changes the evaluative logic: from ''cost to be minimised'' to ''return to be optimised.'' Widely used in debates about education, infrastructure, research, and climate. Compare: als Investition betrachten (to view as an investment), die Rendite von X (the return on X), Cost-Benefit-Analyse (cost-benefit analysis).","examples":[{"sentence":"Bildungsausgaben sind keine Kosten, sondern Investitionen in das Humankapital.","translation":"Education expenditures are not costs, but investments in human capital."},{"sentence":"Gesundheitsversorgung ist keine Ausgabe, sondern eine Investition in die Arbeitsfähigkeit.","translation":"Healthcare is not an expenditure, but an investment in the capacity to work."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Herzstück'' means?","options":["cornerstone/centrepiece","core","heart","foundation"],"correctAnswer":"cornerstone/centrepiece"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The debt brake is the fiscal policy cornerstone of Germany''s consolidation course: as a constitutional requirement, it limits structural deficits to 0.35% of GDP, thereby preventing both cyclical policy flexibility and long-term public investment — a restriction whose balance between fiscal discipline and investment requirements remains politically contested.","options":["Die Schuldenbremse ist das fiscalpolitische Herzstück des deutschen Konsolidierungskurses: Als Verfassungsgebot limitiert sie strukturelle Defizite auf 0,35% des BIPs und verhindert damit sowohl konjunkturpolitische Flexibilität als auch langfristige öffentliche Investitionen — eine Restriktion, deren Ausgewogenheit zwischen Haushaltsdisziplin und Investitionserfordernissen politisch umstritten bleibt.","Die Schuldenbremse begrenzt strukturelle Defizite und schränkt Investitionen ein.","Deutschland hat eine der strengsten Schuldenbremsen der Welt.","Die Schuldenbremse verhindert öffentliche Investitionen, die Deutschland braucht."],"correctAnswer":"Die Schuldenbremse ist das fiscalpolitische Herzstück des deutschen Konsolidierungskurses: Als Verfassungsgebot limitiert sie strukturelle Defizite auf 0,35% des BIPs und verhindert damit sowohl konjunkturpolitische Flexibilität als auch langfristige öffentliche Investitionen — eine Restriktion, deren Ausgewogenheit zwischen Haushaltsdisziplin und Investitionserfordernissen politisch umstritten bleibt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bildungsausgaben sind keine Kosten, sondern Investitionen in das ___.","options":["Humankapital","Bildungssystem","Wissen","Kapital"],"correctAnswer":"Humankapital"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Healthcare is not an expenditure but an investment in the capacity to work","wordBankItems":["Gesundheitsversorgung","ist","keine","Ausgabe",",","sondern","eine","Investition","in","die","Arbeitsfähigkeit","."],"correctAnswer":"Gesundheitsversorgung ist keine Ausgabe , sondern eine Investition in die Arbeitsfähigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Konsumtiv'' means?","options":["consumptive","current","immediate","operational"],"correctAnswer":"consumptive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss inflation and monetary policy at B2","Use Inflation und Geldpolitik vocabulary","Talk about the ECB, Germany''s inflation trauma, and post-COVID inflation"],"explanation":{"intro":"Inflation and monetary policy vocabulary covers Germany''s inflation history, ECB policy, and the post-COVID inflation debate at B2.","culturalNote":"Inflation und Geldpolitik: Germany: Hyperinflation 1923 (Weimarer Republik — Papiergeldflut — wheelbarrows of banknotes — traumatic collective memory — shaped Bundesbank''s hawkish inflation stance). Bundesbank (Deutsche Bundesbank — Frankfurt — globally respected for inflation-fighting credibility — pre-ECB). ECB (Europäische Zentralbank — Frankfurt — Maastricht mandate: price stability — 2% inflation target). Post-COVID inflation 2021-2023: Germany 10% peak 2022 — energy shock (Russia Ukraine) — supply chain disruption. ECB response: fastest rate hike cycle in history (0% → 4.5%). Key debate: Inflation as supply shock or monetary phenomenon? Transitory vs. structural. Lohn-Preis-Spirale (wage-price spiral — feared but largely avoided). Kaufkraft (purchasing power). Real interest rate vs. nominal."},"examples":[{"german":"Deutschlands besonderes Verhältnis zur Inflation ist geschichtlich geprägt: Die Hyperinflation von 1923, die das Ersparte einer ganzen Generation vernichtete, hat sich im kollektiven Gedächtnis als Trauma eingeschrieben und die Geldpolitik der Bundesbank — strikt auf Preisstabilität ausgerichtet — sowie die Skepsis gegenüber einer expansiven EZB-Politik mitgeprägt.","english":"Germany''s special relationship with inflation is shaped by history: the hyperinflation of 1923, which destroyed the savings of an entire generation, has inscribed itself in collective memory as a trauma and has co-shaped the monetary policy of the Bundesbank — strictly directed at price stability — as well as scepticism towards an expansionary ECB policy."},{"german":"Geldpolitik steht vor einem Grunddilemma: Preisstabilität erfordert restriktive Maßnahmen — höhere Zinsen, knappe Liquidität — die wirtschaftliches Wachstum bremsen; ein konjunkturelles Einbrechen wiederum erfordert expansive Maßnahmen — niedrige Zinsen, Liquiditätszufuhr — die Inflationsrisiken erhöhen. Die EZB navigiert in diesem Spannungsfeld zwischen mandat-konformer Inflation und Konjunkturstabilisierung.","english":"Monetary policy faces a fundamental dilemma: price stability requires restrictive measures — higher interest rates, tight liquidity — that slow economic growth; a cyclical downturn in turn requires expansive measures — low interest rates, liquidity supply — that increase inflation risks. The ECB navigates in this tension between mandate-compliant inflation and economic stabilisation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s inflation trauma, ECB monetary policy, and the inflation-growth dilemma at B2."}}',
'{"items":[{"word":"geprägt","translation":"shaped","pronunciation":"geh-PREGT","example":"Geschichtlich geprägt."},{"word":"vernichten","translation":"to destroy","pronunciation":"fer-NIKH-ten","example":"Ersparte vernichten."},{"word":"restriktiv","translation":"restrictive","pronunciation":"res-trik-TEEF","example":"Restriktive Maßnahmen."},{"word":"expansiv","translation":"expansive","pronunciation":"eks-pan-ZEEF","example":"Expansive Geldpolitik."},{"word":"die Liquidität","translation":"liquidity","pronunciation":"dee li-kwi-di-TÄT","example":"Knappe Liquidität."},{"word":"das Mandat","translation":"mandate","pronunciation":"dahs man-DAHT","example":"Mandat der EZB."}]}',
'{"title":"In diesem Spannungsfeld zwischen X und Y navigieren — to navigate in this tension between X and Y","pattern":"in einem Spannungsfeld zwischen X und Y navigieren = to navigate in a tension between X and Y (Spannungsfeld = field of tension; navigieren = to navigate; zwischen X und Y = between X and Y — marks the constrained space between two competing imperatives)","explanation":"Spannungsfeld = field of tension (Spannung = tension; Feld = field — a space defined by competing forces). Navigieren = to navigate (move through a constrained space). In diesem Spannungsfeld zwischen mandat-konformer Inflation und Konjunkturstabilisierung navigieren = to navigate in this tension between mandate-compliant inflation and economic stabilisation. The phrase acknowledges that the actor (ECB, government) has no ideal solution — they must balance competing demands. Compare: zwischen Hammer und Amboss (between a rock and a hard place — more colloquial), auf Messers Schneide (on a knife''s edge — more precarious), einen Mittelweg finden (to find a middle path — more solution-oriented), abwägen (to weigh up — more deliberative).","examples":[{"sentence":"Die Regierung navigiert in einem Spannungsfeld zwischen Sicherheit und Bürgerfreiheiten.","translation":"The government navigates in a tension between security and civil liberties."},{"sentence":"Ärzte navigieren in einem Spannungsfeld zwischen Patientenwillen und medizinischer Notwendigkeit.","translation":"Doctors navigate in a tension between patient will and medical necessity."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Expansiv'' means?","options":["expansive","loose","accommodative","stimulative"],"correctAnswer":"expansive"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s special relationship with inflation is shaped by history: the hyperinflation of 1923, which destroyed the savings of an entire generation, has inscribed itself in collective memory as a trauma and has co-shaped the monetary policy of the Bundesbank — strictly directed at price stability — as well as scepticism towards an expansionary ECB policy.","options":["Deutschlands besonderes Verhältnis zur Inflation ist geschichtlich geprägt: Die Hyperinflation von 1923, die das Ersparte einer ganzen Generation vernichtete, hat sich im kollektiven Gedächtnis als Trauma eingeschrieben und die Geldpolitik der Bundesbank — strikt auf Preisstabilität ausgerichtet — sowie die Skepsis gegenüber einer expansiven EZB-Politik mitgeprägt.","Die Erfahrung mit der Hyperinflation 1923 macht Deutsche besonders inflationssensibel.","Deutschlands Angst vor Inflation geht auf die Hyperinflation der Weimarer Republik zurück.","Die Bundesbank war hart gegen Inflation — ein Erbe der 1923er Katastrophe."],"correctAnswer":"Deutschlands besonderes Verhältnis zur Inflation ist geschichtlich geprägt: Die Hyperinflation von 1923, die das Ersparte einer ganzen Generation vernichtete, hat sich im kollektiven Gedächtnis als Trauma eingeschrieben und die Geldpolitik der Bundesbank — strikt auf Preisstabilität ausgerichtet — sowie die Skepsis gegenüber einer expansiven EZB-Politik mitgeprägt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Regierung navigiert in einem Spannungsfeld zwischen Sicherheit und ___.","options":["Bürgerfreiheiten","Freiheit","Grundrechten","Liberalismus"],"correctAnswer":"Bürgerfreiheiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Doctors navigate in a tension between patient will and medical necessity","wordBankItems":["Ärzte","navigieren","in","einem","Spannungsfeld","zwischen","Patientenwillen","und","medizinischer","Notwendigkeit","."],"correctAnswer":"Ärzte navigieren in einem Spannungsfeld zwischen Patientenwillen und medizinischer Notwendigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vernichten'' means?","options":["to destroy","to annihilate","to eliminate","to wipe out"],"correctAnswer":"to destroy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002e4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss European economic policy at B2","Use Europäische Wirtschaftspolitik vocabulary","Talk about the euro, Eurozone crisis, and EU economic governance"],"explanation":{"intro":"European economic policy vocabulary covers the euro, Eurozone crisis, and EU economic governance at B2.","culturalNote":"Europäische Wirtschaftspolitik: Key: Eurozone (19→20 countries — 2023 Croatia joined — ECB monetary policy). Maastricht Criteria (convergence criteria: inflation, debt, deficit, exchange rate). Stabilitäts- und Wachstumspakt (SGP — 3% deficit limit, 60% debt-to-GDP). Eurozone crisis 2010-2012 (Greece, Portugal, Ireland, Spain, Italy — sovereign debt crisis — ESM — European Stability Mechanism — troika — Schuldenschnitt). Draghi ''Whatever it takes'' (2012 — OMT — saved euro). Eurobonds debate (Merkel: ''not in my lifetime'' — mutualisation of debt). TARGET2 imbalances (Germany: massive claims on ECB — Germany as creditor). NextGenerationEU (COVID recovery — €750bn — grant+loans — first common EU debt). Key reform: Banking Union (SSM, SRM — incomplete without EDIS). Competitiveness report (Draghi 2024 — Europe''s strategic gaps)."},"examples":[{"german":"Die Eurokrise hat ein grundlegendes Konstruktionsproblem der Eurozone freigelegt: Eine einheitliche Geldpolitik ohne flankierende Fiskalpolitik ist inhärent instabil — wenn Staaten in Rezessionen nicht abwerten und keine gemeinsamen Stabilisierungsmechanismen greifen, müssen interne Anpassungen durch schmerzhafte Lohn- und Ausgabenkürzungen erfolgen, die soziale Kosten auf die schwächsten Mitglieder konzentrieren.","english":"The euro crisis revealed a fundamental construction problem of the eurozone: a unified monetary policy without flanking fiscal policy is inherently unstable — when states in recessions cannot devalue and no common stabilisation mechanisms take effect, internal adjustments must take place through painful wage and spending cuts that concentrate social costs on the weakest members."},{"german":"NextGenerationEU markiert eine historische Verschiebung in der europäischen Wirtschaftspolitik: Zum ersten Mal nahm die EU gemeinsam Schulden auf und verteilte einen Teil als Zuschüsse — ein Durchbruch der Solidargemeinschaft, der das Tabu gemeinschaftlicher Schulden unter dem Druck der Pandemie gebrochen hat, aber die Frage offenlässt, ob er precedentprägend oder Ausnahme bleibt.","english":"NextGenerationEU marks a historic shift in European economic policy: for the first time, the EU took on debt jointly and distributed part of it as grants — a breakthrough of the solidarity community that broke the taboo of communal debt under the pressure of the pandemic, but leaves open the question of whether it remains precedent-setting or an exception."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Eurozone crisis, the euro''s construction problem, and NextGenerationEU at B2."}}',
'{"items":[{"word":"flankierend","translation":"flanking/supporting","pronunciation":"flan-KEE-rend","example":"Flankierende Fiskalpolitik."},{"word":"inhärent","translation":"inherent","pronunciation":"in-HÄ-rent","example":"Inhärent instabil."},{"word":"abwerten","translation":"to devalue","pronunciation":"AB-ver-ten","example":"Währung abwerten."},{"word":"der Zuschuss","translation":"grant","pronunciation":"dayr TSOO-shooss","example":"Zuschüsse verteilen."},{"word":"das Tabu","translation":"taboo","pronunciation":"dahs tah-BOO","example":"Tabu brechen."},{"word":"precedentprägend","translation":"precedent-setting","pronunciation":"pre-ZEH-dent-prä-gend","example":"Precedentprägend oder Ausnahme?"}]}',
'{"title":"Die Frage offenlassen, ob X oder Y — to leave open the question of whether X or Y","pattern":"etwas lässt die Frage offen, ob X oder Y = something leaves open the question of whether X or Y (offenlassen = to leave open — separable; die Frage offen = the question open; ob...oder = whether...or — indirect question)","explanation":"Die Frage offenlassen, ob X oder Y = to leave open the question of whether X or Y (offenlassen — separable: lässt...offen). Marks that a situation does not resolve a key question — it remains genuinely open. Lässt die Frage offen, ob der Durchbruch precedentprägend oder Ausnahme bleibt = leaves open the question of whether the breakthrough remains precedent-setting or an exception. Often used at the end of a complex argument: a decisive question remains unresolved after the analysis. Compare: offen ist, ob (what is open is whether), unklar bleibt, ob (what remains unclear is whether — more epistemic), unentschieden (undecided), nicht entschieden (not decided).","examples":[{"sentence":"Die Studie lässt die Frage offen, ob die Maßnahmen langfristig wirksam sind.","translation":"The study leaves open the question of whether the measures are effective in the long term."},{"sentence":"Das Urteil lässt offen, ob dies auch in anderen Fällen gilt.","translation":"The judgement leaves open whether this also applies in other cases."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Inhärent'' means?","options":["inherent","intrinsic","fundamental","structural"],"correctAnswer":"inherent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The euro crisis revealed a fundamental construction problem of the eurozone: a unified monetary policy without flanking fiscal policy is inherently unstable — when states in recessions cannot devalue and no common stabilisation mechanisms take effect, internal adjustments must take place through painful wage and spending cuts that concentrate social costs on the weakest members.","options":["Die Eurokrise hat ein grundlegendes Konstruktionsproblem der Eurozone freigelegt: Eine einheitliche Geldpolitik ohne flankierende Fiskalpolitik ist inhärent instabil — wenn Staaten in Rezessionen nicht abwerten und keine gemeinsamen Stabilisierungsmechanismen greifen, müssen interne Anpassungen durch schmerzhafte Lohn- und Ausgabenkürzungen erfolgen, die soziale Kosten auf die schwächsten Mitglieder konzentrieren.","Der Euro ist strukturell instabil ohne gemeinsame Fiskalpolitik.","Eurokrise-Länder mussten Löhne und Ausgaben kürzen, weil sie nicht abwerten konnten.","Die Eurozone ist auf Dauer nicht stabil ohne fiskalischen Ausgleichsmechanismus."],"correctAnswer":"Die Eurokrise hat ein grundlegendes Konstruktionsproblem der Eurozone freigelegt: Eine einheitliche Geldpolitik ohne flankierende Fiskalpolitik ist inhärent instabil — wenn Staaten in Rezessionen nicht abwerten und keine gemeinsamen Stabilisierungsmechanismen greifen, müssen interne Anpassungen durch schmerzhafte Lohn- und Ausgabenkürzungen erfolgen, die soziale Kosten auf die schwächsten Mitglieder konzentrieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Studie lässt die Frage offen, ob die Maßnahmen langfristig ___ sind.","options":["wirksam","effektiv","erfolgreich","wirkungsvoll"],"correctAnswer":"wirksam"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The judgement leaves open whether this also applies in other cases","wordBankItems":["Das","Urteil","lässt","offen",",","ob","dies","auch","in","anderen","Fällen","gilt","."],"correctAnswer":"Das Urteil lässt offen , ob dies auch in anderen Fällen gilt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Zuschuss'' means?","options":["grant","subsidy","funding","support"],"correctAnswer":"grant"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

